import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @param {any} config - node configuration
 * @param {any} ctx - runtime context
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root container (position/rotation/scale will be applied by the adapter)
  const root = new Group();

  // --------------------------------------------------------------------
  // Plane background – brushed metal texture
  // --------------------------------------------------------------------
  const planeMaterial = new MeshBasicNodeMaterial();
  // Base surface colour (fallback to spec surface colour)
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {};
  planeMaterial.color = new Color(colors.surface ?? '#0b0b10');

  // Load the brushed‑metal map asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMaterial.map = tex;
      planeMaterial.needsUpdate = true;
    });
  }

  const planeMesh = new Mesh(new PlaneGeometry(1, 1), planeMaterial);
  // Slightly raise the plane so text can sit just above it
  planeMesh.position.set(0, 0, 0);
  root.add(planeMesh);

  // --------------------------------------------------------------------
  // Text overlay (CTA label)
  // --------------------------------------------------------------------
  const textItems =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const textColor = colors.paper ?? '#e8ecf2';

  for (const item of textItems) {
    const fontSize = item.typography?.fontSize ?? 42;
    const txtObj = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: textColor,
      align: 'center',
    });
    // Position text just above the plane
    txtObj.position.set(0, 0, 0.01);
    root.add(txtObj);
  }

  // --------------------------------------------------------------------
  // Apply cinematic primitives (if any)
  // --------------------------------------------------------------------
  const primitiveHandles = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(root, prim.params);
      primitiveHandles.push(handle);
    }
  }

  // --------------------------------------------------------------------
  // Event handlers placeholder (no interactions defined)
  // --------------------------------------------------------------------
  root.userData.handlers = {};

  // --------------------------------------------------------------------
  // Cleanup – dispose resources and kill GSAP timelines
  // --------------------------------------------------------------------
  root.userData.cleanup = () => {
    // Dispose geometry & material
    planeMesh.geometry.dispose();
    planeMaterial.dispose();

    // Clean up any primitive resources
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') {
        h.cleanup();
      }
    }

    // Kill any GSAP tweens that might target this node
    gsap.killTweensOf(root);
  };

  return root;
}
